  tenant_id        uuid not null references public.tenant(id) on delete restrict,
  status           public.entity_status not null default 'draft',
  label            text not null check (char_length(label) <= 120),
  amount_minor     bigint not null default 0,
  currency         char(3) not null default 'IDR',
  metadata         jsonb not null default '{}'::jsonb check (pg_column_size(metadata) <= 16384),
  version          integer not null default 1,
  idempotency_key  text,
  trace_id         text,
  region           text,
  checksum         bytea,
  created_by       uuid,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  deleted_at       timestamptz
);
create unique index if not exists core_batch_idem_uq on wealth.core_batch (tenant_id, idempotency_key) where deleted_at is null;
create index if not exists core_batch_status_ix on wealth.core_batch (tenant_id, status, created_at desc);
create index if not exists core_batch_updated_ix on wealth.core_batch (tenant_id, updated_at desc);
create index if not exists core_batch_meta_ix on wealth.core_batch using gin (metadata jsonb_path_ops);
create index if not exists core_batch_pending_ix on wealth.core_batch (tenant_id) where status = 'pending';
drop trigger if exists core_batch_touch on wealth.core_batch;
create trigger core_batch_touch before update on wealth.core_batch for each row execute function public.touch_updated_at();
alter table wealth.core_batch enable row level security;
drop policy if exists core_batch_tenant_isolation on wealth.core_batch;
create policy core_batch_tenant_isolation on wealth.core_batch
  using (tenant_id = nullif(current_setting('app.tenant', true), '')::uuid);

